<?= $this->section('scripts') ?><script>$(function(){$('.audit-detail').on('click',function(){const b=$(this);$('#farmassist-audit-action-value').text(b.data('action'));$('#farmassist-audit-time-value').text(b.data('time'));let context=b.attr('data-context')||'';try{context=JSON.stringify(JSON.parse(context),null,2);}catch(e){}$('#farmassist-audit-context-value').text(context||'No additional context recorded.');});});</script><?= $this->endSection() ?>
